function [st] = stribeck_excess(om, f_static, coulomb, w_stribeck, fscale)
%STRIBECK_EXCESS  The breakaway excess [N m] over Coulomb at speed om: (f_static - coulomb) fscale e^(-(om/w_s)^2) sign(om).
%   om: real[1] (passed a plain number)
%   f_static: real[1] (passed a plain number)
%   coulomb: real[1] (passed a plain number)
%   w_stribeck: real[1] (passed a plain number)
%   fscale: real[1] (passed a plain number)
%   returns st: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    st = 0;
    x = (om / w_stribeck);
    st = ((((f_static - coulomb) * fscale) * exp(((-(x)) * x))) * sign(om));
end
